{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Piritrexim, which shares the 2,4-diaminopyrimidine and dimethoxyphenylmethyl core with the query, showed 43% absolute oral bioavailability in patients, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Trimazosin, a trimethoxy aminoquinazoline with a piperazine carboxamide, had 63% oral bioavailability in healthy men, supporting high oral absorption for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Alfuzosin, a methoxy-substituted aminoquinazoline amide, had 64.5% absolute oral bioavailability in healthy subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Betrixaban, a larger amidine/chloroamide with methoxy and multiple aromatic rings, had 34% absolute oral bioavailability in humans, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Omeprazole, a methoxy-substituted heteroaromatic drug with challenging solubility, had 30-40% absolute oral bioavailability, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Rigosertib, a high-molecular-weight polyaromatic anticancer agent, had 34.8% absolute oral bioavailability in fasting patients, supporting F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite the unfavorable physicochemical prior, the closest structural analogue piritrexim and several related heteroaromatic/methoxy-containing drugs show absolute oral bioavailability well above 20%, so the query is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data are available for the query molecule.",
    "Food effects and formulation dependence are unknown; some analogues show lower bioavailability in fed states.",
    "The high molecular weight, TPSA, and lipophilicity may reduce absorption relative to smaller analogues, but the threshold is only 20%.",
    "Metabolic clearance and efflux susceptibility are not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

